def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Background is the most frequent cell value.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # All non-background cells in these puzzles form one relevant colour.
    non_bg_vals = [v for v in vals if v != bg]
    if not non_bg_vals:
        return out.tolist()

    # If multiple non-background colours exist, choose the one with
    # the most cells (examples use a single object colour).
    obj = non_bg_vals[0]
    for v in non_bg_vals[1:]:
        if np.sum(g == v) > np.sum(g == obj):
            obj = int(v)
    obj = int(obj)

    mask = (g == obj)

    def component_cells(seed):
        seen = set()
        dq = deque([seed])
        seen.add(seed)
        while dq:
            r, c = dq.popleft()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and mask[nr, nc]:
                        seen.add((nr, nc))
                        dq.append((nr, nc))
        return seen

    # Collect 8-connected components.
    comp_id = {}
    comps = []
    for r in range(h):
        for c in range(w):
            if mask[r, c] and (r, c) not in comp_id:
                cells = component_cells((r, c))
                cid = len(comps)
                for cell in cells:
                    comp_id[cell] = cid
                comps.append(cells)

    if not comps:
        return out.tolist()

    # Canonical shape: coordinates relative to top-left cell.
    def shape_key(cells):
        min_r = min(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        return frozenset((r - min_r, c - min_c) for r, c in cells)

    # Anchor: top-left cell.
    def anchor(cells):
        min_r = min(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        return (min_r, min_c)

    anchors = [anchor(cells) for cells in comps]
    shapes = [shape_key(cells) for cells in comps]

    # Find a translation that maps at least one component to another component
    # with the same shape. Prefer diagonal translations; if none, use vertical.
    candidates = []
    for i, cells_i in enumerate(comps):
        ai = anchors[i]
        for j, cells_j in enumerate(comps):
            if i == j:
                continue
            if shapes[i] != shapes[j]:
                continue
            aj = anchors[j]
            dr = aj[0] - ai[0]
            dc = aj[1] - ai[1]
            if dr == 0 and dc == 0:
                continue
            # The moved copy must fit in bounds and match cells exactly.
            ok = True
            for r, c in cells_i:
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w) or g[nr, nc] != obj:
                    ok = False
                    break
            if ok:
                score = 0
                if dr != 0 and dc != 0:
                    score += 1000
                # Prefer larger absolute displacement, and positive direction.
                score += abs(dr) + abs(dc)
                if dr > 0:
                    score += 10
                if dc > 0:
                    score += 5
                candidates.append((score, dr, dc, i, j))

    if candidates:
        candidates.sort(reverse=True)
        best_dr, best_dc = candidates[0][1], candidates[0][2]
    else:
        # Fallback observed in examples without an exact diagonal duplicate:
        # project anchors upward by 5 rows.
        best_dr, best_dc = -5, 0

    # Move direction is opposite to the found positive displacement,
    # or upward by 5 if no displacement was found.
    move_dr, move_dc = -best_dr, -best_dc

    # For each component, move its anchor.
    # If the moved anchor lands on an existing component, colour the whole
    # component; otherwise place a single marker.
    marker = 9
    one_marker = 1

    moved_points = []
    full_component_ids = set()

    for cid, cells in enumerate(comps):
        ar, ac = anchors[cid]
        nr, nc = ar + move_dr, ac + move_dc
        if 0 <= nr < h and 0 <= nc < w:
            if mask[nr, nc]:
                full_component_ids.add(comp_id[(nr, nc)])
            else:
                moved_points.append((nr, nc))

    # Default marker colour is 9. In rows containing an odd symmetric set of
    # moved single points, the middle point is coloured 1.
    by_row = {}
    for r, c in moved_points:
        by_row.setdefault(r, []).append(c)

    single_colors = {}
    for r, cs in by_row.items():
        cs = sorted(cs)
        if len(cs) == 3:
            a, b, c = cs
            if b - a == c - b:
                single_colors[(r, b)] = one_marker

    for r, c in moved_points:
        out[r, c] = single_colors.get((r, c), marker)

    for cid in full_component_ids:
        for r, c in comps[cid]:
            out[r, c] = marker

    # Ensure integer values 0-9.
    out = np.clip(out, 0, 9).astype(int)
    return out.tolist()

import numpy as np
from collections import defaultdict, deque

def _components(mask):
    h, w = mask.shape
    seen = np.zeros((h, w), bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    rr, cc = q.popleft()
                    cells.append((rr, cc))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = rr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and mask[nr, nc] and not seen[nr, nc]:
                                seen[nr, nc] = True
                                q.append((nr, nc))
                comps.append(cells)
    return comps

def _norm(cells):
    mr = min(r for r, _ in cells)
    mc = min(c for _, c in cells)
    return frozenset((r - mr, c - mc) for r, c in cells)

def _top_left(cells):
    mr = min(r for r, _ in cells)
    mc = min(c for _, c in cells if r == mr)
    return mr, mc

def _top_cell(cells):
    mr = min(r for r, _ in cells)
    mc = min(c for _, c in cells if r == mr)
    return mr, mc

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Background: most common value.
    vals, cnts = np.unique(a, return_counts=True)
    bg = int(vals[np.argmax(cnts)])

    # Object color: most common non-background value.
    nonbg = [v for v in vals if int(v) != bg]
    if not nonbg:
        return a.astype(int).tolist()
    obj = int(nonbg[0])
    for v in nonbg[1:]:
        if np.sum(a == v) > np.sum(a == obj):
            obj = int(v)

    out = a.copy()
    mask = (a == obj)
    comps = _components(mask)

    # Representative point:
    # - For V-like shapes (single top cell), use top cell.
    # - For L-like shapes with two top cells, use top-left cell.
    reps = []
    for cells in comps:
        minr = min(r for r, _ in cells)
        top_cells = [c for r, c in cells if r == minr]
        if len(top_cells) == 1:
            reps.append((minr, top_cells[0], len(cells) > 1))
        else:
            reps.append((minr, min(top_cells), len(cells) > 1))

    # Base vertical projection: 5 cells above the representative.
    marks = {}
    for r, c, keep in reps:
        if not keep:
            continue
        nr, nc = r - 5, c
        if 0 <= nr < h and 0 <= nc < w:
            marks.setdefault((nr, nc), []).append(('base', 9))

    # If there is an exact diagonal component translation by (-5, -5),
    # apply it to all same-shape components.
    shape_map = {}
    for i, cells in enumerate(comps):
        shape_map.setdefault(_norm(cells), []).append(i)

    diag = None
    for sh, idxs in shape_map.items():
        anchors = {}
        for i in idxs:
            anchors[_top_left(comps[i])] = i
        for (r1, c1), i in anchors.items():
            t = (r1 - 5, c1 - 5)
            if t in anchors and anchors[t] != i:
                diag = (-5, -5)
                break
        if diag:
            break

    if diag:
        dr, dc = diag
        for sh, idxs in shape_map.items():
            anchors = {}
            for i in idxs:
                anchors[_top_left(comps[i])] = i
            for i in idxs:
                r, c = _top_left(comps[i])
                tr, tc = r + dr, c + dc
                if (tr, tc) in anchors:
                    for rr, cc in comps[anchors[(tr, tc)]]:
                        out[rr, cc] = 9
                    marks.setdefault((tr, tc), []).append(('diag_full', 9))
                elif 0 <= tr < h and 0 <= tc < w:
                    marks.setdefault((tr, tc), []).append(('diag_point', 9))

    # Place marks. If a base mark and a diagonal mark coincide, use 1.
    for (r, c), lst in marks.items():
        kinds = {kind for kind, _ in lst}
        if 'base' in kinds and ('diag_point' in kinds or 'diag_full' in kinds):
            out[r, c] = 1
        else:
            out[r, c] = 9

    # If exactly three base marks share a row, recolor the median one 1.
    by_row = defaultdict(list)
    for (r, c), lst in marks.items():
        if any(kind == 'base' for kind, _ in lst):
            by_row[r].append(c)

    for r, cs in by_row.items():
        cs = sorted(set(cs))
        if len(cs) == 3:
            mid = cs[1]
            # Prefer 1 only if this cell is not already forced to 9 by diag overlap.
            kinds = {kind for kind, _ in marks[(r, mid)]}
            if not ('diag_point' in kinds or 'diag_full' in kinds):
                out[r, mid] = 1

    return np.clip(out, 0, 9).astype(int).tolist()

