                label += 1
                stack = [(r, c)]
                visited[r, c] = True
                while stack:
                    y, x = stack.pop()
                    labels[y, x] = label
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if mask[ny, nx] and not visited[ny, nx]:
                                    visited[ny, nx] = True
                                    stack.append((ny, nx))

    def top_side(cells: list[tuple[int, int]]) -> bool:
        color = int(grid[cells[0][0]][cells[0][1]])

        # Primary rule: odd colours go top, even colours go bottom.
        if color % 2 == 1:
            return True
        if color % 2 == 0:
            return False

        # Fallback for any unexpected non-integer-like colour behaviour:
        # use the component's vertical centre of mass.
        ys = [y for y, _ in cells]
        return (sum(ys) / len(ys)) <= (h - 1) / 2.0

    moved = {}
    for lab in range(1, label + 1):
        cells = [(r, c) for r in range(h) for c in range(w) if labels[r, c] == lab]
        if not cells:
            continue

        top = top_side(cells)
        top_rows = [y for y, _ in cells]
        bottom_rows = [y for y, _ in cells]
        new_top = 0 if top else h - (max(bottom_rows) - min(top_rows) + 1)
        dy = new_top - min(top_rows)
        moved[lab] = dy

    # Erase all original non-background pixels.
    out[mask] = bg

    # Repaint components at their new vertical positions.
    for lab, dy in moved.items():
