        return g.astype(int).tolist()

    # For each component, count cells on even/odd rows (0-indexed).
    # In the examples, components with more cells on odd rows go to the top,
    # components with more cells on even rows go to the bottom.
    # If tied, use the color parity fallback (odd color -> top, even -> bottom).
    top_components = []
    bottom_components = []

    for lab in range(1, next_label + 1):
        ys, xs = np.where(labels == lab)
        color = int(g[ys[0], xs[0]])

        odd_rows = np.count_nonzero((ys % 2) == 1)
        even_rows = len(ys) - odd_rows

        if odd_rows > even_rows:
            top_components.append((lab, color, ys, xs))
        elif even_rows > odd_rows:
            bottom_components.append((lab, color, ys, xs))
        else:
            if color % 2 == 1:
                top_components.append((lab, color, ys, xs))
            else:
                bottom_components.append((lab, color, ys, xs))

    # Clear all non-background cells.
    out = np.full((h, w), bg, dtype=int)

    def place(components, at_top: bool):
        # Preserve relative horizontal ordering from input.
        # Since components do not overlap in the examples, simple alignment is enough.
        # To be robust, keep their original columns and only translate vertically.
        for lab, color, ys, xs in components:
            min_y = int(ys.min())
            max_y = int(ys.max())
            height = max_y - min_y + 1
            if at_top:
                offset = -min_y
            else:
                offset = (h - height) - min_y

            for y, x in zip(ys, xs):
                ny = y + offset
                if 0 <= ny < h:
                    out[ny, x] = color

    # Place bottom components first, then top, so if unexpected overlaps occur,
    # top components remain visible. The examples have no overlaps.
    place(bottom_components, False)
    place(top_components, True)

    return out.astype(int).tolist()

import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])

    # Flood fill the area containing all 6s.
    # Treat every non-1 cell as traversable background.
    region = [[False] * w for _ in range(h)]
    q = deque()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                region[r][c] = True
                q.append((r, c))

    # 4-way connectivity for the background area.
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if not region[nr][nc] and grid[nr][nc] != 1:
                    region[nr][nc] = True
                    q.append((nr, nc))

    # Find 1-components (4-way) that touch the background region diagonally/orthogonally.
    visited_1 = [[False] * w for _ in range(h)]
    out = [[8] * w for _ in range(h)]

    def neigh8(r, c):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    yield nr, nc

    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] == 1 and not visited_1[sr][sc]:
                comp = []
                dq = deque([(sr, sc)])
                visited_1[sr][sc] = True
                touches_region = False

                while dq:
                    r, c = dq.popleft()
                    comp.append((r, c))

                    # 8-neighbor touch to the filled background region
                    for nr, nc in neigh8(r, c):
                        if region[nr][nc]:
                            touches_region = True
                            break
                    if touches_region:
                        # Can still keep expanding, but no need to check every neighbour further.
                        pass

                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == 1 and not visited_1[nr][nc]:
                                visited_1[nr][nc] = True
                                dq.append((nr, nc))

                if touches_region:
                    for r, c in comp:
                        out[r][c] = 1

    # Paint 7 on the boundary of the 6-region:
    # - cells on the grid edge, or
    # - cells with a 1 in their 8-neighborhood.
    for r in range(h):
        for c in range(w):
            if not region[r][c]:
                continue
            if grid[r][c] == 6:
                out[r][c] = 6
                continue

            is_edge = (r == 0 or r == h - 1 or c == 0 or c == w - 1)
            near_1 = False
            for nr, nc in neigh8(r, c):
                if grid[nr][nc] == 1:
                    near_1 = True
                    break

            if is_edge or near_1:
                out[r][c] = 7
            else:
                out[r][c] = 8

    # Keep any 6s that were not in the flood-filled region? In this puzzle the 6 is
    # the source, but this makes the behavior safe.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                out[r][c] = 6

    return out

