            mask_seen = set()
            frame_cells = 0
            hole_cells = 0
            for r in range(h):
                for c in range(w):
                    if (r, c) in mask_seen:
                        continue
                    if grid[r][c] == fr:
                        comp = find_component((r, c), fr)
                        frame_cells += len(comp)
                        mask_seen.update(comp)
                    elif grid[r][c] == hr:
                        comp = find_component((r, c), hr)
                        hole_cells += len(comp)
                        mask_seen.update(comp)
                    else:
                        break
                else:
                    continue
                break
            else:
                if frame_cells >= 10 and hole_cells >= 10:
                    score = frame_cells * hole_cells
                    if best is None or score > best[0]:
                        best = (score, fr, hr, set(mask_seen))

    if best is None:
        return [row[:] for row in grid]

    _, fr, hr, mask_cells = best

    mask = [[hr if (r, c) in mask_cells else fr for c in range(w)] for r in range(h)]

