                if not all(0 <= r < h and 0 <= c < w for r, c in moved):
                    continue
                if not any(mask[r][c] == hr for r, c in moved):
                    continue
                overlap = sum(1 for r, c in moved if out[r][c] != fr)
                if best_pl is None or overlap < best_pl[0]:
