def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    # Find every maximal vertical run whose first and last cells have the same
    # non-zero colour E and whose interior (if any) is a single other colour F.
    runs = []  # (endpoint_colour, fill_colour, top_row, bottom_row, col)
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == 0:
                r += 1
                continue
            r2 = r
            while r2 + 1 < h and grid[r2 + 1][c] != 0:
                r2 += 1

            top_col = grid[r][c]
            bot_col = grid[r2][c]

            if top_col != 0 and top_col == bot_col:
                interior = set(grid[x][c] for x in range(r + 1, r2))
                # A valid "bar" has at least one interior cell, all of one colour
                # different from the endpoint colour.
                if len(interior) == 1 and next(iter(interior)) != top_col and r2 > r + 1:
                    fill_col = next(iter(interior))
                    runs.append((top_col, fill_col, r, r2, c))

            r = r2 + 1

    if not runs:
        return out

    # Group runs by endpoint colour and fill colour.
    groups = {}
    for run in runs:
        e, f = run[0], run[1]
        groups.setdefault((e, f), []).append(run)

    # Select one run per group:
    # - if the fill colour is 7, take the leftmost run;
    # - otherwise take the rightmost run.
    for (e, f), runs_in_group in groups.items():
        if len(runs_in_group) == 1:
            selected = runs_in_group[0]
        elif f == 7:
            selected = min(runs_in_group, key=lambda x: x[4])  # leftmost column
        else:
            selected = max(runs_in_group, key=lambda x: x[4])  # rightmost column

        _, fill_color, top, bottom, c = selected
        for rr in range(top + 1, bottom):
            if out[rr][c] == fill_color:
                out[rr][c] = e

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
