            min_r = min(y for y, _ in cells)
            max_r = max(y for y, _ in cells)
            min_c = min(x for _, x in cells)
            max_c = max(x for _, x in cells)

            height = max_r - min_r + 1
            width = max_c - min_c + 1
            area = len(cells)
            center_c = (min_c + max_c) // 2

            if height == 1 and width == 5 and area == 5 and min_r == h - 1:
                markers.append({"color": color, "center": center_c, "cells": cells})
            elif height == 3 and width == 5 and area == 11:
                shapes.append({"color": color, "top": min_r, "center": center_c, "cells": cells})

    # Group shapes by column centre.
    by_col = defaultdict(list)
    for s in shapes:
        by_col[s["center"]].append(s)

    def column_stack(col):
        """Return the dominant colour in this column and how many objects it has."""
        if col not in by_col:
            return None, 0
        stats = {}
        for s in by_col[col]:
            color = s["color"]
            if color not in stats:
                stats[color] = {"count": 0, "max_top": -1}
            stats[color]["count"] += 1
            stats[color]["max_top"] = max(stats[color]["max_top"], s["top"])
        best_color = None
        best_key = None
        for color, info in stats.items():
            key = (info["count"], info["max_top"])
            if best_key is None or key > best_key:
                best_key = key
                best_color = color
        return best_color, stats[best_color]["count"]

    out = [row[:] for row in grid]

    def draw_object(r, c, color):
        # Diamond object:
        #  111
        # 11111
        #  111
        for dc in (-1, 0, 1):
            out[r][c + dc] = color
        for dc in (-2, -1, 0, 1, 2):
            out[r + 1][c + dc] = color
        for dc in (-1, 0, 1):
            out[r + 2][c + dc] = color

    # Columns marked by 2: their main colour becomes 5.
    # Their total number of objects tells how far the 3-column object extends upward.
    two_cols = {m["center"] for m in markers if m["color"] == 2}
    extend_amount = 0

    for col in two_cols:
        color, count = column_stack(col)
        if color is None:
            continue
        extend_amount += count
        if color != 5:
            for s in by_col[col]:
                if s["color"] == color:
                    for y, x in s["cells"]:
                        out[y][x] = 5

    # Columns marked by 3: extend their main colour upward by extend_amount slots.
    three_cols = {m["center"] for m in markers if m["color"] == 3}
    for col in three_cols:
        color, _ = column_stack(col)
        if color is None:
            continue
        tops = [s["top"] for s in by_col[col] if s["color"] == color]
        if not tops:
            continue
        top = min(tops)
        for i in range(1, extend_amount + 1):
            nr = top - 4 * i
            if nr < 0 or nr + 2 >= h:
                break
            draw_object(nr, col, color)

    # Remove the bottom-row marker bars.
    for m in markers:
        for y, x in m["cells"]:
            out[y][x] = bg

    return out

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Normalize input to a plain 2D list of ints.
    input_grid = [[int(v) for v in row] for row in grid]
    h = len(input_grid)
    w = len(input_grid[0]) if h else 0

    out = [row[:] for row in input_grid]
    q = deque()

    # All existing 6s are sources.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 6:
                q.append((r, c))

    while q:
        r, c = q.popleft()

        if r + 1 >= h:
            continue

        # Move downward through background 7s.
        if out[r + 1][c] == 7:
            out[r + 1][c] = 6
            q.append((r + 1, c))
            continue

        # If this 6 is directly above a 2, spread horizontally across the top
        # of that horizontal 2-run, plus one open cell on each side if present.
        if input_grid[r + 1][c] == 2:
            left = c
            while left > 0 and out[r][left - 1] != 2 and input_grid[r + 1][left - 1] == 2:
                left -= 1
            if left > 0 and out[r][left - 1] != 2 and input_grid[r + 1][left - 1] != 2:
                left -= 1

            right = c
            while right + 1 < w and out[r][right + 1] != 2 and input_grid[r + 1][right + 1] == 2:
                right += 1
            if right + 1 < w and out[r][right + 1] != 2 and input_grid[r + 1][right + 1] != 2:
                right += 1

            for x in range(left, right + 1):
                if out[r][x] == 7:
                    out[r][x] = 6
                    q.append((r, x))

    return out

import sys
from collections import Counter, defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0

    # Background is the most frequent colour (also the border colour in the examples).
    bg = Counter(map(tuple, (tuple(row) for row in grid))).most_common(1)[0][0] if False else None
    cnt = Counter()
    for r in range(H):
        for c in range(W):
            cnt[grid[r][c]] += 1
    bg = cnt.most_common(1)[0][0]

    # Find all non-background 4-connected components.
    visited = [[False] * W for _ in range(H)]
    components = []

    def cell_ok(r, c):
        return 0 <= r < H and 0 <= c < W and grid[r][c] != bg and not visited[r][c]

    for r in range(H):
        for c in range(W):
            if cell_ok(r, c):
                col = grid[r][c]
                stack = [(r, c)]
                visited[r][c] = True
                cells = []
                min_r = max_r = r
                min_c = max_c = c
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    min_r = min(min_r, y)
                    max_r = max(max_r, y)
                    min_c = min(min_c, x)
                    max_c = max(max_c, x)
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if cell_ok(ny, nx) and grid[ny][nx] == col:
                            visited[ny][nx] = True
                            stack.append((ny, nx))

                h = max_r - min_r + 1
                w = max_c - min_c + 1

                # Complete 3x5 diamond: 11 cells in a 3x5 bounding box.
                if h == 3 and w == 5 and len(cells) == 11:
                    # Verify exact shape.
                    ok = True
                    pattern = [(0, 1), (0, 2), (0, 3),
                               (1, 0), (1, 1), (1, 2), (1, 3), (1, 4),
                               (2, 1), (2, 2), (2, 3)]
                    for dy, dx in pattern:
                        y, x = min_r + dy, min_c + dx
                        if not (0 <= y < H and 0 <= x < W) or grid[y][x] != col:
                            ok = False
                            break
                    # Corners must be background.
                    if ok:
                        for dy, dx in ((0, 0), (0, 4), (2, 0), (2, 4)):
                            y, x = min_r + dy, min_c + dx
                            if not (0 <= y < H and 0 <= x < W) or grid[y][x] != bg:
                                ok = False
                                break
                    if ok:
                        components.append((min_r, min_c, col, "complete"))
                    else:
                        components.append((min_r, min_c, col, "other"))
                else:
                    components.append((min_r, min_c, col, "other"))

    complete = [x for x in components if x[3] == "complete"]
    others = [x for x in components if x[3] != "complete"]

    # Markers are 1x5 horizontal bars in the bottom row.
    markers = []
    for (r, c, col, kind) in others:
        if r == H - 1:
            # Check it is exactly a 5-cell horizontal bar.
            if r == max(r for _ in [r]) and all(grid[r][cc] == col for cc in range(c, c + 5)):
                # Ensure no other non-background cells in this component outside the bar.
                size = sum(1 for rr in range(r, min(r + 2, H)) for cc in range(c, c + 5) if grid[rr][cc] == col)
                if size == 5:
                    markers.append((c, col))

    # Group complete objects by column (left coordinate).
    by_col = defaultdict(list)
    for r, c, col, _ in complete:
        by_col[c].append((r, col))

    out = [[bg] * W for _ in range(H)]

    def draw_diamond(r, c, color):
        pattern = [(0, 1), (0, 2), (0, 3),
                   (1, 0), (1, 1), (1, 2), (1, 3), (1, 4),
                   (2, 1), (2, 2), (2, 3)]
        for dy, dx in pattern:
            y, x = r + dy, c + dx
            if 0 <= y < H and 0 <= x < W:
                out[y][x] = color

    # If there are no markers, just return the original complete objects without partial bars.
    if len(markers) != 2:
        for r, c, col, _ in complete:
            draw_diamond(r, c, col)
        return out

    markers = markers[:2]
    (c1, mc1), (c2, mc2) = markers

    # The marker with the larger colour identifies the column to extend.
    if mc1 >= mc2:
        sel_col, chg_col = c1, c2
    else:
        sel_col, chg_col = c2, c1

    sel_objects = by_col.get(sel_col, [])
    chg_objects = by_col.get(chg_col, [])

    # Colour for the extended column: use its complete objects; if absent, use its marker colour.
    if sel_objects:
        sel_color = Counter(col for _, col in sel_objects).most_common(1)[0][0]
    else:
        sel_color = mc1 if sel_col == c1 else mc2

    # Total number of objects to place in the selected column:
    # original selected objects + objects from the changed column.
    total = len(sel_objects) + len(chg_objects)

    # Anchor the extended column at the bottommost selected object.
    if sel_objects:
        bottom_r = max(r for r, _ in sel_objects)
    elif chg_objects:
        bottom_r = max(r for r, _ in chg_objects)
    else:
        bottom_r = H - 4  # safe fallback

    # Draw the extended selected column as a contiguous vertical run of length total.
    for i in range(total):
        r = bottom_r - 4 * i
        if 0 <= r and r + 2 < H:
            draw_diamond(r, sel_col, sel_color)
        else:
            break

    # Change all objects in the changed column to colour 5.
    for r, _ in chg_objects:
        draw_diamond(r, chg_col, 5)

    # Keep all complete objects that are not in the two marked columns.
    for r, c, col, _ in complete:
        if c not in (sel_col, chg_col):
            draw_diamond(r, c, col)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0
    out = [row[:] for row in grid]

    # 1) Replace every horizontal 777 segment by 868, and put 6s in the
    #    adjacent non-empty (frame) rows above/below its center.
    for r in range(H):
        c = 0
        while c < W:
            if (grid[r][c] == 7 and
                c + 2 < W and
                grid[r][c + 1] == 7 and
                grid[r][c + 2] == 7):
                out[r][c] = 8
                out[r][c + 1] = 6
                out[r][c + 2] = 8

                for nr in (r - 1, r + 1):
                    if 0 <= nr < H and out[nr][c + 1] != 0:
                        out[nr][c + 1] = 6

                c += 3
            else:
                c += 1

    def frame_centers(r: int) -> list[int]:
        """Centers of 777 segments in a frame/empty row (input)."""
        if r < 0 or r >= H:
            return []
        res = []
        c = 0
        while c < W:
            if (grid[r][c] == 7 and
                c + 2 < W and
                grid[r][c + 1] == 7 and
                grid[r][c + 2] == 7):
                res.append(c + 1)
                c += 3
            else:
                c += 1
        return res

    # 2) Determine which sides of each frame row should receive 3s.
    #
    # Compare the horizontal span of the 777 segments in the two neighboring
    # non-frame rows:
    #   min/max both increase  -> left side marked
    #   min/max both decrease  -> right side marked
    #   span contracts         -> both sides marked
    #   span expands           -> no side marked
    # Top row: no 3s.  Bottom row: both sides marked if there are 7s above.
    for r in range(0, H, 2):
        left_mark = False
        right_mark = False

        if r == 0:
            pass
        elif r == H - 1:
            above = frame_centers(r - 1)
            if above:
                left_mark = True
                right_mark = True
        else:
            above = frame_centers(r - 1)
            below = frame_centers(r + 1)

            if above and below:
                amin, amax = min(above), max(above)
                bmin, bmax = min(below), max(below)

                # Strictly shift right or contract on the left.
                if bmin > amin:
                    left_mark = True
                # Strictly shift left or contract on the right.
                if bmax < amax:
                    right_mark = True

        if left_mark or right_mark:
            # Clear old 3s in this frame row; keep 0 holes.
            for c in range(W):
                if out[r][c] == 3:
                    out[r][c] = 8

            # Put 3s on marked sides.  Normal behavior is a two-cell edge cap.
            # If the row contains holes, use a one-cell edge cap (when an old
            # edge 3 existed) and also mark the side of each hole facing away
            # from the nearer border.
            has_hole = any(out[r][c] == 0 for c in range(W))

            if left_mark:
                if has_hole:
                    if out[r][0] == 3:
                        out[r][0] = 3
                else:
                    out[r][0] = 3
                    if W > 1:
                        out[r][1] = 3

            if right_mark:
                if has_hole:
                    if out[r][W - 1] == 3:
                        out[r][W - 1] = 3
                else:
                    out[r][W - 1] = 3
                    if W > 1:
                        out[r][W - 2] = 3

            if has_hole:
                for c in range(W):
                    if out[r][c] == 0:
                        left_dist = c
                        right_dist = W - 1 - c
                        if left_dist < right_dist:
                            nc = c + 1
                        else:
                            nc = c - 1
                        if 0 <= nc < W and out[r][nc] == 8:
                            out[r][nc] = 3

    # 3) Ensure odd/non-frame rows do not keep stale 3s from input.
    for r in range(1, H, 2):
        for c in range(W):
            if out[r][c] == 3:
                out[r][c] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0
    out = [row[:] for row in grid]

    def centers_7(r: int) -> list[int]:
        if r < 0 or r >= H:
            return []
        res = []
        c = 0
        while c < W:
            if c + 2 < W and grid[r][c] == 7 and grid[r][c + 1] == 7 and grid[r][c + 2] == 7:
                res.append(c + 1)
                c += 3
            else:
                c += 1
        return res

    def holes(r: int) -> list[int]:
        if r < 0 or r >= H:
            return []
        return [c for c in range(W) if grid[r][c] == 0]

    # 1) Convert every 777 into 868, and put 6 in the corresponding center
    #    positions in the frame rows immediately above and below.
    for r in range(H):
        c = 0
        while c < W:
            if (c + 2 < W and
                grid[r][c] == 7 and
                grid[r][c + 1] == 7 and
                grid[r][c + 2] == 7):
                out[r][c] = 8
                out[r][c + 1] = 6
                out[r][c + 2] = 8

                mid = c + 1
                if r - 1 >= 0 and out[r - 1][mid] != 0:
                    out[r - 1][mid] = 6
                if r + 1 < H and out[r + 1][mid] != 0:
                    out[r + 1][mid] = 6

                c += 3
            else:
                c += 1

    # 2) For each frame row, decide which sides receive 3s.
    #
    # For each side of a frame row, use the horizontal positions of 777 centers
    # in the adjacent odd row.  If that adjacent row is absent or has no 777,
    # fall back to the 0-holes in the frame row itself.  This naturally handles
    # grid borders and empty rows.
    for r in range(0, H, 2):
        top = centers_7(r - 1) if r > 0 else holes(r)
        if not top:
            top = holes(r)

        bottom = centers_7(r + 1) if r + 1 < H else holes(r)
        if not bottom:
            bottom = holes(r)

        left_mark = False
        right_mark = False

        if top and bottom:
            tmin, tmax = min(top), max(top)
            bmin, bmax = min(bottom), max(bottom)
            if bmin > tmin:
                left_mark = True
            if bmax < tmax:
                right_mark = True

        # No marks on the top boundary of the whole grid.
        if r == 0:
            left_mark = False
            right_mark = False

        if not (left_mark or right_mark):
            continue

        is_boundary = (r == 0 or r == H - 1)
        has_hole = any(grid[r][c] == 0 for c in range(W))
        thick = 0 if is_boundary else (0 if has_hole else 1)

        # Clear old 3s in this frame row, then write the new edge markers.
        for c in range(W):
            if out[r][c] == 3:
                out[r][c] = 8

        if left_mark:
            out[r][0] = 3
            if thick and W > 1:
                out[r][1] = 3

        if right_mark:
            out[r][W - 1] = 3
            if thick and W > 1:
                out[r][W - 2] = 3

        # If the frame row contains holes, put a 3 next to each hole on the
        # marked side.  When both sides are marked, choose the farther side.
        if has_hole:
            for c in range(W):
                if grid[r][c] == 0:
                    if left_mark and right_mark:
                        choose_left = c <= (W - 1) // 2
                    else:
                        choose_left = left_mark

                    nc = c - 1 if choose_left else c + 1
                    if 0 <= nc < W and out[r][nc] == 8:
                        out[r][nc] = 3

    # 3) Non-frame rows must not contain 3s.
    for r in range(1, H, 2):
        for c in range(W):
            if out[r][c] == 3:
                out[r][c] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.asarray(grid, dtype=int)
    H, W = a.shape

    # Start from the original grid.
    out = a.copy()

    # Find all 4-connected components of 0s.
    seen = np.zeros((H, W), dtype=bool)
    components = []

    for r in range(H):
        for c in range(W):
            if a[r, c] == 0 and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                comp = []
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if a[ny, nx] == 0 and not seen[ny, nx]:
                                seen[ny, nx] = True
                                stack.append((ny, nx))
                components.append(comp)

    # Keep only zero components that do not touch the border and are "small enough"
    # (the intended hidden rule only outlines isolated interior zero holes).
    for comp in components:
        if any(r == 0 or c == 0 or r == H - 1 or c == W - 1 for r, c in comp):
            continue
        if len(comp) > 4:
            continue

        comp_set = set(comp)
