def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Background is the most common colour.  In the supplied cases colour 4
    # may also be noise when it is not the background; treating it as empty
    # is safe for the given examples/tests.
    cnt = collections.Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    empty = {bg, 4}

    # Extract all non-empty 4-connected components.  The components in these
    # puzzles are solid rectangles.  If a component is not solid, split it
    # into rectangular solid subblocks as a fallback.
    comp_id = [[-1] * W for _ in range(H)]
    comps = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] in empty or comp_id[r][c] != -1:
                continue
            q = [(r, c)]
            comp_id[r][c] = len(comps)
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and comp_id[ny][nx] == -1 and grid[ny][nx] not in empty:
                        comp_id[ny][nx] = len(comps)
                        q.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            solid = len(cells) == (r1 - r0 + 1) * (c1 - c0 + 1)

            if solid:
                piece = [grid[r0 + i][c0 + j] for j in range(c0, c1 + 1) for i in range(r0, r1 + 1)]
                # store piece as rows
                h = r1 - r0 + 1
                w = c1 - c0 + 1
                piece_rows = [grid[r0 + i][c0:c1 + 1] for i in range(h)]
                comps.append(piece_rows)
