                                    break
                            if not ok:
                                break
                            h += 1
                        w = 1
                        while c + w <= c1:
                            ok = True
                            for rr in range(r, r + h):
                                if grid[rr][c + w] in empty:
                                    ok = False
                                    break
                            if not ok:
                                break
                            w += 1
                        # make it a valid solid block
                        w = 1
                        while c + w <= c1:
                            ok = True
                            for rr in range(r, r + h):
