                            if not ok:
                                break
                            w += 1
                        w -= 1
                        if h == 1 and w == 1:
                            comps.append([[grid[r][c]]])
                            seen.add((r, c))
                        else:
                            piece = [grid[rr][cc:cc + w] for rr in range(r, r + h)]
                            comps.append(piece)
                            for rr in range(r, r + h):
                                for cc in range(c, c + w):
