    if not piece_col_count:
        return [row[:] for row in grid]
    frame = max(piece_col_count.items(), key=lambda x: (x[1], x[0]))[0]

    def edge(p, side):
        # side: 0 top, 1 right, 2 bottom, 3 left
        h = len(p)
        w = len(p[0])
        if side == 0:
            return tuple(p[0])
        if side == 1:
            return tuple(p[i][w - 1] for i in range(h))
        if side == 2:
            return tuple(p[h - 1])
        return tuple(p[i][0] for i in range(h))

    def compatible(a, b):
        # Frames can touch arbitrary content, and equal non-frame content is
        # preferred.  This avoids rejecting valid arrangements where a frame
        # line borders ordinary tile content.
        if len(a) != len(b):
            return False
        score = 0
        for x, y in zip(a, b):
            if x == frame or y == frame:
                score += 1
            elif x == y:
                score += 1
            else:
                return False
        return True

    # Try to pack all pieces, without rotation, into the smallest possible
    # rectangle.  Search dimensions in increasing area/height, and use a
    # depth-first placement over the first empty cell.  The search order is
    # biased by the input position of each piece to recover the intended
    # arrangement when several packings are possible.
    pieces = comps
    n = len(pieces)
    area = sum(len(p) * len(p[0]) for p in pieces)

    # input anchor for each piece (centre, rounded)
    anchors = []
    for p in pieces:
