                continue
            stack = [(i, j)]
            seen[i, j] = True
            r0 = c0 = i = j
            r1 = c1 = i = j
            while stack:
                r, c = stack.pop()
                r0 = min(r0, r); r1 = max(r1, r)
                c0 = min(c0, c); c1 = max(c1, c)
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and g[nr, nc] != 8:
                        seen[nr, nc] = True
                        stack.append((nr, nc))
            boxes.append((r0, c0, r1, c1))

    def crop(r0, c0, r1, c1):
        return g[r0:r1 + 1, c0:c1 + 1]

    def mirror_h(a):
