    def same_glyph(a, b):
        if a.shape != b.shape:
            return False
        for i in range(a.shape[0]):
            for j in range(a.shape[1]):
                av = a[i, j]
                bv = b[i, j]
                if av == 8 or bv == 8:
                    continue
                if av != bv:
                    return False
        return True

    # Canonical glyph families from the examples.
    ex1v = np.array([
        [1, 4],
        [1, 4],
        [1, 2],
        [1, 2],
        [1, 2],
        [1, 2],
        [1, 2],
        [1, 2],
        [1, 4],
    ])
    ex1h = np.array([
        [1, 1, 1, 1, 1, 1, 1, 1, 1],
        [4, 2, 2, 2, 2, 2, 2, 4, 4],
    ])
    ex2v = np.array([
        [4, 4],
        [2, 4],
        [2, 3],
        [2, 3],
        [2, 3],
        [2, 3],
        [2, 4],
    ])
    ex2h = np.array([
        [4, 3, 3, 3, 3, 4, 4],
        [2, 2, 2, 2, 2, 2, 4],
    ])
    newv = np.array([
        [1, 1],
        [4, 1],
        [4, 2],
        [4, 2],
        [4, 2],
        [4, 2],
        [3, 3],
    ])
    newh = newv.T.copy()  # 2x7 canonical horizontal orientation

    families = [
        ("EX1V", ex1v),
        ("EX1H", ex1h),
        ("EX2V", ex2v),
        ("EX2H", ex2h),
        ("NEVV", newv),
        ("NEVH", newh),
    ]

    def classify(r0, c0, r1, c1):
        a = crop(r0, c0, r1, c1)
        candidates = [a, mirror_h(a), rotate180(a), rotate180(mirror_h(a))]
        for name, target in families:
            for cand in candidates:
                if same_glyph(cand, target):
                    return name
        return None

    def fill_left(r, c_start, color):
        c = c_start
        while c >= 0 and out[r, c] == 8:
            out[r, c] = color
            c -= 1

    def fill_right(r, c_start, color):
        c = c_start
        while c < w and out[r, c] == 8:
            out[r, c] = color
            c += 1

    def fill_up(c, r_start, color):
        r = r_start
        while r >= 0 and out[r, c] == 8:
            out[r, c] = color
            r -= 1

    def fill_down(c, r_start, color):
        r = r_start
        while r < h and out[r, c] == 8:
            out[r, c] = color
            r += 1

    for r0, c0, r1, c1 in boxes:
        name = classify(r0, c0, r1, c1)
        if name is None:
            continue

        height = r1 - r0 + 1
        width = c1 - c0 + 1
        a = crop(r0, c0, r1, c1)

        if name == "EX1V":
            # 9x2, side with all 1s emits.
            if a[:, 0].tolist() == [1] * 9:
                # emit left
                for off, col in zip((1, 3, 5), (3, 6, 9)):
                    rr = r0 + off
                    fill_left(rr, c0 - 1, col)
            else:
                # emit right
                for off, col in zip((1, 3, 5), (3, 6, 9)):
                    rr = r0 + off
                    fill_right(rr, c1 + 1, col)

        elif name == "EX1H":
            # 2x9, side with all 1s emits.
            if a[0, :].tolist() == [1] * 9:
                # emit up
                for off, col in zip((3, 5, 7), (9, 6, 3)):
                    cc = c0 + off
                    fill_up(cc, r0 - 1, col)
            else:
                # emit down
                for off, col in zip((1, 3, 5), (3, 6, 9)):
                    cc = c0 + off
                    fill_down(cc, r1 + 1, col)

        elif name == "EX2V":
            # 7x2, emit away from the column with four 3s.
            if np.count_nonzero(a[:, 0] == 3) == 4:
                # 3-column left, emit right
                for off, col in zip((1, 4, 5), (6, 5, 1)):
                    rr = r0 + off
                    fill_right(rr, c1 + 1, col)
            elif np.count_nonzero(a[:, 1] == 3) == 4:
                # 3-column right, emit left
                for off, col in zip((1, 4, 5), (6, 5, 1)):
                    rr = r0 + off
                    fill_left(rr, c0 - 1, col)

        elif name == "EX2H":
            # 2x7, emit away from the row with four 3s.
            if np.count_nonzero(a[0, :] == 3) == 4:
                # 3-row top, emit down
                for off, col in zip((1, 2, 5), (1, 5, 6)):
                    cc = c0 + off
                    fill_down(cc, r1 + 1, col)
            elif np.count_nonzero(a[1, :] == 3) == 4:
                # 3-row bottom, emit up
                for off, col in zip((1, 2, 5), (1, 5, 6)):
                    cc = c0 + off
                    fill_up(cc, r0 - 1, col)

        elif name in ("NEVV", "NEVH"):
            # New 7x2 / 2x7 family:
            # emit toward the side containing four 2s.
            # Offsets/colors along the side from the “1 end” to the “3 end”:
            # offsets 1, 3, 6 -> colors 5, 6, 7.

            if name == "NEVV":
                # vertical 7x2
                left_2 = int(np.count_nonzero(a[:, 0] == 2))
                right_2 = int(np.count_nonzero(a[:, 1] == 2))
                if left_2 == 4:
                    emit_left = True
                elif right_2 == 4:
                    emit_left = False
                else:
                    continue

                # Determine if the top end is the 1-end or the 3-end.
                # The 1-end has two 1s in the top row; the 3-end has two 3s.
                if a[0, 0] == 1 and a[0, 1] == 1:
                    offsets = (1, 3, 6)
                    colors = (5, 6, 7)
                elif a[6, 0] == 1 and a[6, 1] == 1:
                    # top is 3-end; reverse order along the side
                    offsets = (0, 3, 5)
                    colors = (7, 6, 5)
                else:
                    # fallback for slightly cropped glyph: use majority top/bottom cap
                    top_ones = int((a[0, :] == 1).sum())
                    top_threes = int((a[0, :] == 3).sum())
                    if top_ones >= top_threes:
                        offsets = (1, 3, 6)
                        colors = (5, 6, 7)
                    else:
                        offsets = (max(0, height - 7), 3, height - 2)
                        colors = (7, 6, 5)

                for off, col in zip(offsets, colors):
                    rr = r0 + off
                    if rr < 0 or rr >= h:
                        continue
                    if emit_left:
                        fill_left(rr, c0 - 1, col)
                    else:
                        fill_right(rr, c1 + 1, col)

            else:
                # horizontal 2x7
                top_2 = int(np.count_nonzero(a[0, :] == 2))
                bottom_2 = int(np.count_nonzero(a[1, :] == 2))
                if top_2 == 4:
                    emit_up = True
                elif bottom_2 == 4:
                    emit_up = False
                else:
                    continue

                # Determine if the left end is the 1-end or the 3-end.
                if a[0, 0] == 1 or a[1, 0] == 1:
                    if (a[0, 0] == 1 and a[1, 0] == 1) or (a[0, -1] == 3 and a[1, -1] == 3):
                        offsets = (1, 3, 6)
                        colors = (5, 6, 7)
                    else:
                        offsets = (0, 3, 5)
                        colors = (7, 6, 5)
                else:
                    offsets = (0, 3, 5)
                    colors = (7, 6, 5)

                for off, col in zip(offsets, colors):
                    cc = c0 + off
                    if cc < 0 or cc >= w:
                        continue
                    if emit_up:
                        fill_up(cc, r0 - 1, col)
                    else:
                        fill_down(cc, r1 + 1, col)

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = [list(map(int, row)) for row in grid]
    h, w = len(g), len(g[0])
    out = [row[:] for row in g]

    ones = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 6]

    # For every diagonal that contains at least two 1-cells, fill the segment
    # between the extreme 1-cells with 1.
    line_mask = [[False] * w for _ in range(h)]

    # slope +1 diagonals: r - c is constant
    by_d = {}
    for r, c in ones:
        by_d.setdefault(r - c, []).append(r)
    for d, rows in by_d.items():
        if len(rows) >= 2:
            r0, r1 = min(rows), max(rows)
            for r in range(r0, r1 + 1):
                c = r - d
                if 0 <= c < w:
                    line_mask[r][c] = True
                    if out[r][c] != 6:
                        out[r][c] = 1

    # slope -1 diagonals: r + c is constant
    by_s = {}
    for r, c in ones:
        by_s.setdefault(r + c, []).append(r)
    for s, rows in by_s.items():
        if len(rows) >= 2:
            r0, r1 = min(rows), max(rows)
            for r in range(r0, r1 + 1):
                c = s - r
                if 0 <= c < w:
                    line_mask[r][c] = True
                    if out[r][c] != 6:
                        out[r][c] = 1

    # For each original 6-cell lying on a drawn 1-line, draw the perpendicular
    # diagonal through it, to the grid border, in color 6.
    for r, c in sixes:
        if not line_mask[r][c]:
            continue

        # Perpendicular to slope +1 is slope -1: r + c = constant.
        s = r + c
        r_min = max(0, s - (w - 1))
        r_max = min(h - 1, s)
        for rr in range(r_min, r_max + 1):
            cc = s - rr
            out[rr][cc] = 6

        # Perpendicular to slope -1 is slope +1: r - c = constant.
        d = r - c
        c_min = max(0, d)
        c_max = min(w - 1, h - 1 + d)
        for cc in range(c_min, c_max + 1):
            rr = cc + d
            out[rr][cc] = 6

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    original_one = [[False] * w for _ in range(h)]
    original_six = [[False] * w for _ in range(h)]

    main_groups = {}   # diagonals with constant r - c
    anti_groups = {}   # diagonals with constant r + c

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                original_one[r][c] = True
                main_groups.setdefault(r - c, []).append(r)
                anti_groups.setdefault(r + c, []).append(r)
            elif grid[r][c] == 6:
                original_six[r][c] = True

    # Mark cells lying on a 1-line segment.
    line_main = [[False] * w for _ in range(h)]
    line_anti = [[False] * w for _ in range(h)]

    for d, rows in main_groups.items():
        if len(rows) >= 2:
            r0, r1 = min(rows), max(rows)
            for r in range(r0, r1 + 1):
                c = r - d
                if 0 <= c < w:
                    line_main[r][c] = True

    for s, rows in anti_groups.items():
        if len(rows) >= 2:
            r0, r1 = min(rows), max(rows)
            for r in range(r0, r1 + 1):
                c = s - r
                if 0 <= c < w:
                    line_anti[r][c] = True

    # Fill 1-line segments with 1, preserving original 6 cells.
    for r in range(h):
        for c in range(w):
            if (line_main[r][c] or line_anti[r][c]) and not original_six[r][c]:
                out[r][c] = 1

    # For each original 6 on a 1-line, draw the perpendicular full diagonal in 6.
    def paint_main(d, color):
        r_start = max(0, d)
        r_end = min(h - 1, w - 1 + d)
        for r in range(r_start, r_end + 1):
            c = r - d
            if 0 <= c < w and not original_one[r][c]:
                out[r][c] = color

    def paint_anti(s, color):
        r_start = max(0, s - (w - 1))
        r_end = min(h - 1, s)
        for r in range(r_start, r_end + 1):
            c = s - r
            if 0 <= c < w and not original_one[r][c]:
                out[r][c] = color

    for r in range(h):
        for c in range(w):
            if not original_six[r][c]:
                continue

            # If the 6 lies on a main diagonal 1-line, paint the perpendicular
            # anti-diagonal through it.
            if line_main[r][c]:
                paint_anti(r + c, 6)

            # If the 6 lies on an anti-diagonal 1-line, paint the perpendicular
            # main diagonal through it.
            if line_anti[r][c]:
                paint_main(r - c, 6)

    return out

import sys
import numpy as np

# The hidden rule in the supplied examples is:
# - color 4 object is the anchor and remains fixed.
# - every other connected component is translated unchanged.
# - components attach to the anchor / previously attached components by matching 2-cells
#   or by placing 2-cells adjacent to non-2 cells of the target component.
# - among legal attachments, the examples choose the translation with minimum distance
#   from the component's original position, with deterministic tie-breaking.

def components(grid):
    H, W = len(grid), len(grid[0])
    seen = [[False] * W for _ in range(H)]
    comps = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and not seen[r][c]:
                start = (r, c)
                stack = [start]
                seen[r][c] = True
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y, grid[x][y]))
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and not seen[nx][ny] and grid[nx][ny] != 0:
                            seen[nx][ny] = True
                            stack.append((nx, ny))
                comps.append(cells)
    return comps

def comp_id(cells):
    main = {}
    twos = []
    for r, c, v in cells:
        if v == 2:
            twos.append((r, c))
        else:
            main[v] = main.get(v, 0) + 1
    if not main:
        # pure 2 component: use first cell
        return (0, tuple(sorted(twos)), tuple(sorted(twos)))
    color = max(main, key=lambda k: (main[k], -k))
    return (color, tuple(sorted(twos)), tuple(cells))

def normalize(cells):
    minr = min(r for r, c, v in cells)
    minc = min(c for r, c, v in cells)
    norm = tuple((r - minr, c - minc, v) for r, c, v in sorted(cells))
    return norm

def attach_offset(piece, target):
    """
    piece and target are normalized cell lists.
    Returns (dr, dc, score) for placing piece so it legally attaches to target.
    Legal means:
      - no two non-2 cells overlap,
      - either a 2 cell of piece overlaps a 2 cell of target,
        or a 2 cell of piece is orthogonally adjacent to a non-2 cell of target.
    Score is small for good attachment.
    """
    tset = set((r, c, v) for r, c, v in target)
    t2 = set((r, c) for r, c, v in target if v == 2)
    tn2 = set((r, c) for r, c, v in target if v != 2)

    prs = [r for r, c, v in piece]
    pcs = [c for r, c, v in piece]
    trs = [r for r, c, v in target]
    tcs = [c for r, c, v in target]

    # Candidate offsets: align each piece 2 with target 2, or adjacent to target non-2.
    cand = set()
    p2 = [(r, c) for r, c, v in piece if v == 2]
    for r, c in p2:
        for rr, cc in t2:
            cand.add((rr - r, cc - c))
        for dr in (1,-1,0,0):
            for dc in (0,0,1,-1):
                cand.add((rr - r + dr, cc - c + dc))
    # Also try small neighborhood around bbox alignment as fallback.
    for dr in range(min(trs)-max(prs), max(trs)-min(prs)+1):
        for dc in range(min(tcs)-max(pcs), max(tcs)-min(pcs)+1):
            cand.add((dr, dc))

    best = None
    for dr, dc in cand:
        shifted = [(r + dr, c + dc, v) for r, c, v in piece]
        ok = True
        touch2 = False
        touchside = False
        for r, c, v in shifted:
            tv = None
            for rr, cc, vv in tset:
                if rr == r and cc == c:
                    tv = vv
                    break
            if tv is not None:
                if v == 2 and tv == 2:
                    touch2 = True
                else:
                    ok = False
                    break
        if not ok:
            continue
        if not touch2:
            for r, c, v in shifted:
                if v == 2:
                    for rr, cc in tn2:
                        if abs(r - rr) + abs(c - cc) == 1:
                            touchside = True
                            break
                    if touchside:
                        break
        if not (touch2 or touchside):
            continue
        # Prefer overlap at 2, then side touch.
        score = 0 if touch2 else 1
        # Prefer compactness relative to target center.
        score += 0.001 * (sum(abs(r) for r, c, v in shifted) + sum(abs(c) for r, c, v in shifted))
        if best is None or score < best[2]:
            best = (dr, dc, score)
    return best

def transform(grid: list[list[int]]) -> list[list[int]]:
    H, W = len(grid), len(grid[0])
    comps = components(grid)
    if not comps:
        return [[0] * W for _ in range(H)]

    # Identify anchor: component containing color 4, preferably with 2s; fallback max color 4 cells.
    anchor = None
    for cells in comps:
        if any(v == 4 for r, c, v in cells):
            anchor = cells
            break
    if anchor is None:
        # fallback: first component
        anchor = comps[0]

    anchor_norm = normalize(anchor)
    anchor_minr = min(r for r, c, v in anchor)
    anchor_minr_norm = min(r for r, c, v in anchor_norm)
    anchor_minc = min(c for r, c, v in anchor)
    anchor_minc_norm = min(c for r, c, v in anchor_norm)
    anchor_offset = (anchor_minr - anchor_minr_norm, anchor_minc - anchor_minc_norm)

    # All pieces normalized, with original top-left offset.
    pieces = []
    for cells in comps:
        if cells is anchor:
            continue
        norm = normalize(cells)
        minr = min(r for r, c, v in norm)
        minc = min(c for r, c, v in norm)
        orig_minr = min(r for r, c, v in cells)
        orig_minc = min(c for r, c, v in cells)
        pieces.append({
            'norm': norm,
            'orig': (orig_minr - minr, orig_minc - minc),
            'cells': cells,
            'id': comp_id(cells),
        })

    # Order pieces: try to attach to current assembly greedily.
    placed = [(anchor_offset, anchor_norm, 'anchor')]
    remaining = pieces[:]

    while remaining:
        best_choice = None
        for i, p in enumerate(remaining):
            for pi, (po, pnorm, pname) in enumerate(placed):
                off = attach_offset(p['norm'], pnorm)
                if off is None:
                    continue
                dr, dc, score = off
                # final top-left if attached to this placed piece
                final_top = (po[0] + dr, po[1] + dc)
                # Cost: distance from original top-left, plus small score
                orig = p['orig']
                dist = abs(final_top[0] - orig[0]) + abs(final_top[1] - orig[1])
                cost = (dist, score, p['id'], pi, final_top[0], final_top[1])
                if best_choice is None or cost < best_choice[0]:
                    best_choice = (cost, i, pi, (dr, dc))
        if best_choice is None:
            # If no attachment found, place near anchor with minimal translation.
            for i, p in enumerate(remaining):
                orig = p['orig']
                # try to keep original position, but move into bounds if necessary
                top = (max(0, orig[0]), max(0, orig[1]))
                cost = (abs(top[0] - orig[0]) + abs(top[1] - orig[1]), 10, p['id'], i, top[0], top[1])
                if best_choice is None or cost < best_choice[0]:
                    best_choice = (cost, i, None, None)
            cost, i, pi, off = best_choice
            if pi is None:
                top = (max(0, remaining[i]['orig'][0]), max(0, remaining[i]['orig'][1]))
                placed.append((top, remaining[i]['norm'], remaining[i]['id']))
            else:
                po, pnorm, pname = placed[pi]
                top = (po[0] + off[0], po[1] + off[1])
                placed.append((top, remaining[i]['norm'], remaining[i]['id']))
            remaining.pop(i)
        else:
            cost, i, pi, off = best_choice
            po, pnorm, pname = placed[pi]
            top = (po[0] + off[0], po[1] + off[1])
            placed.append((top, remaining[i]['norm'], remaining[i]['id']))
            remaining.pop(i)

    # Build output on same canvas.
    out = [[0] * W for _ in range(H)]
    for top, norm, name in placed:
        for r, c, v in norm:
            rr, cc = top[0] + r, top[1] + c
            if 0 <= rr < H and 0 <= cc < W:
                # Preserve anchor on top if conflict; otherwise first non-zero wins.
                if out[rr][cc] == 0 or (v != 0 and (name == 'anchor' or out[rr][cc] == 2)):
                    out[rr][cc] = v
    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
