    out = [row[:] for row in grid]

    ones = []
    sixes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                ones.append((r, c))
            elif grid[r][c] == 6:
                sixes.append((r, c))

    # Draw diagonal 1-lines for every diagonal (45 degrees) that contains at least two 1s.
    # Use only background cells (or existing 1 cells); never overwrite 6.
    def fill_1_segment(cells):
        if len(cells) < 2:
            return
        r_min = min(r for r, _ in cells)
        r_max = max(r for r, _ in cells)
        for r in range(r_min, r_max + 1):
            c = r - key if direction == 1 else key - r
            if 0 <= r < h and 0 <= c < w and out[r][c] != 6:
                out[r][c] = 1

    # direction 1: r - c is constant (down-right diagonal)
    groups = {}
    for r, c in ones:
        groups.setdefault(r - c, []).append((r, c))
    for key, cells in groups.items():
        direction = 1
        fill_1_segment(cells)

    # direction 2: r + c is constant (down-left diagonal)
    groups = {}
    for r, c in ones:
        groups.setdefault(r + c, []).append((r, c))
    for key, cells in groups.items():
        direction = 2
        fill_1_segment(cells)

    # For every 6 lying on a drawn 1-segment, draw the perpendicular diagonal through it.
    for r, c in sixes:
        # Check slope +1 line (r - c constant)
        k1 = r - c
        ones_on = [pos for pos in ones if pos[0] - pos[1] == k1]
        if len(ones_on) >= 2:
            r_min = min(pos[0] for pos in ones_on)
            r_max = max(pos[0] for pos in ones_on)
            if r_min <= r <= r_max:
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 6
                    rr -= 1
                    cc -= 1
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 6
                    rr += 1
                    cc += 1

        # Check slope -1 line (r + c constant)
        k2 = r + c
        ones_on = [pos for pos in ones if pos[0] + pos[1] == k2]
        if len(ones_on) >= 2:
            r_min = min(pos[0] for pos in ones_on)
            r_max = max(pos[0] for pos in ones_on)
            if r_min <= r <= r_max:
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 6
                    rr -= 1
                    cc += 1
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 6
                    rr += 1
                    cc -= 1

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    ones = []
    sixes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                ones.append((r, c))
            elif grid[r][c] == 6:
                sixes.append((r, c))

    input_one = set(ones)
    input_six = set(sixes)

    # Diagonal type 0: r - c is constant (down-right).
    # Diagonal type 1: r + c is constant (down-left).
    groups = [[], []]
    for r, c in ones:
        groups[0].append((r - c, r, c))
        groups[1].append((r + c, r, c))

    triggered_sixes = []

    for dtype in (0, 1):
        by_key = {}
        for key, r, c in groups[dtype]:
            by_key.setdefault(key, []).append((r, c))

        for key, cells in by_key.items():
            if len(cells) < 2:
                continue

            r_min = min(r for r, _ in cells)
            r_max = max(r for r, _ in cells)

            # Draw the 1-segment between the outermost 1s on this diagonal.
            for r in range(r_min, r_max + 1):
                if dtype == 0:
                    c = r - key
                else:
                    c = key - r
                if 0 <= r < h and 0 <= c < w and (r, c) not in input_six:
                    out[r][c] = 1

            # Any original 6 on this drawn 1-segment spawns a perpendicular 6 line.
            for r, c in sixes:
                if r < r_min or r > r_max:
                    continue
                if dtype == 0 and (r - c == key):
                    triggered_sixes.append(((r + c), 1, r, c))
                elif dtype == 1 and (r + c == key):
                    triggered_sixes.append(((r - c), 0, r, c))

    # Draw perpendicular 6-lines.
    for const, ptype, r0, c0 in triggered_sixes:
        if ptype == 1:
            # Perpendicular to r-c diagonal: r+c is constant.
            for r in range(h):
                c = const - r
                if 0 <= c < w and (r, c) not in input_one and (r, c) not in input_six:
                    out[r][c] = 6
        else:
            # Perpendicular to r+c diagonal: r-c is constant.
            for r in range(h):
                c = r - const
                if 0 <= c < w and (r, c) not in input_one and (r, c) not in input_six:
                    out[r][c] = 6

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])

    # The border color is the background in all supplied cases.
    bg = grid[0][0]
    # Color 4 is used as a transparent/decoy color when it is not the background.
    ignore = {bg, 4}

    # Extract solid rectangular pieces made of non-ignored colors.
    seen = [[False] * W for _ in range(H)]
    pieces = []

    for r in range(H):
        for c in range(W):
            if seen[r][c] or grid[r][c] in ignore:
                continue

            # Connected component of kept cells (4-neighbor).
            comp = []
            stack = [(r, c)]
            seen[r][c] = True
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W:
                        if not seen[ny][nx] and grid[ny][nx] not in ignore:
                            seen[ny][nx] = True
                            stack.append((ny, nx))

            min_r = min(y for y, _ in comp)
            max_r = max(y for y, _ in comp)
            min_c = min(x for _, x in comp)
            max_c = max(x for _, x in comp)
            ph = max_r - min_r + 1
            pw = max_c - min_c + 1

            # The examples contain only filled rectangular pieces.
            if len(comp) == ph * pw:
                piece = [[grid[y][x] for x in range(min_c, max_c + 1)]
                         for y in range(min_r, max_r + 1)]
                pieces.append((ph, pw, piece))

    if not pieces:
        return [row[:] for row in grid]

    total_area = sum(ph * pw for ph, pw, _ in pieces)
    max_h = max(ph for ph, _, _ in pieces)
    max_w = max(pw for _, pw, _ in pieces)

    candidates = []
    for Ht in range(1, total_area + 1):
        if total_area % Ht:
            continue
        Wt = total_area // Ht
        if Ht >= max_h and Wt >= max_w:
            candidates.append((Ht, Wt))

    # Prefer dimensions close to square, then smaller height/width.
    candidates.sort(key=lambda z: (abs(z[0] - z[1]), z[0], z[1]))

    best_board = None

    for Ht, Wt in candidates:
        # Board cell is None or an int.
        board = [[None] * Wt for _ in range(Ht)]
        used = [False] * len(pieces)

        # Quick edge-consistency test: every border cell of a piece must match
        # the corresponding border cell in the board after any partial placement
        # is impossible; instead we do full exact-cover backtracking with cell
        # conflicts only.  The supplied puzzles have a unique geometric tiling.
        # To disambiguate mirror-like tilings, score final boards by preferring
        # a smooth outer boundary (all border cells of the most common object
        # color) and by stable piece order.

        def first_empty(bd):
            for i in range(Ht):
                row = bd[i]
                for j in range(Wt):
                    if row[j] is None:
                        return i, j
            return None

        def place(bd, pr, pc, ph, pw, piece):
            for i in range(ph):
                for j in range(pw):
                    if bd[pr + i][pc + j] is not None:
                        return False
            for i in range(ph):
                for j in range(pw):
                    bd[pr + i][pc + j] = piece[i][j]
            return True

        def unplace(bd, pr, pc, ph, pw):
            for i in range(ph):
                for j in range(pw):
                    bd[pr + i][pc + j] = None

        solutions = []

        def backtrack():
            pos = first_empty(board)
            if pos is None:
                # Copy board.
                solutions.append([row[:] for row in board])
                return True

            r, c = pos
            for idx, (ph, pw, piece) in enumerate(pieces):
                if used[idx]:
                    continue
                if ph > Ht - r or pw > Wt - c:
                    continue

                # The first empty cell must be the top-left of the rectangle
                # placed there in a tiling.
                if place(board, r, c, ph, pw, piece):
                    used[idx] = True
                    if backtrack():
                        used[idx] = False
                        unplace(board, r, c, ph, pw)
                        return True
                    used[idx] = False
                    unplace(board, r, c, ph, pw)
            return False

        if backtrack():
            if not solutions:
                continue

            # If multiple boards are possible, keep the one with the most
            # uniform boundary color; this matches the observed targets.
            def boundary_score(bd):
                vals = {}
                for i in range(Ht):
                    vals[bd[i][0]] = vals.get(bd[i][0], 0) + 1
                    vals[bd[i][Wt - 1]] = vals.get(bd[i][Wt - 1], 0) + 1
                for j in range(Wt):
                    vals[bd[0][j]] = vals.get(bd[0][j], 0) + 1
                    vals[bd[Ht - 1][j]] = vals.get(bd[Ht - 1][j], 0) + 1
                return max(vals.values())

            if best_board is None or boundary_score(solutions[0]) > boundary_score(best_board):
                best_board = solutions[0]

    if best_board is None:
        # Fallback: return the input cleaned of ignored color (should not happen
        # for the intended test cases).
        return [[0 if v in ignore else v for v in row] for row in grid]

    return best_board

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    sys.setrecursionlimit(10000)

    H = len(grid)
    W = len(grid[0])

    # Background is the border colour in all ARC instances of this family.
    bg = grid[0][0]

    # ------------------------------------------------------------------
    # 1) Find the small 2x2 marker.  It consists of three equal non-bg
    #    cells and one missing cell.  The missing cell is the corner of
    #    the final rectangle.
    # ------------------------------------------------------------------
    marker_color = None
    marker_corner = None
    marker_kind = None

    colors = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != bg:
                colors.setdefault(v, []).append((r, c))

    # Prefer a colour that occurs exactly 3 times and forms an L.
    for v, coords in colors.items():
        if len(coords) != 3:
            continue
        s = set(coords)
        for r in range(H - 1):
            for c in range(W - 1):
                cells = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
                if sum(1 for p in cells if p in s) == 3:
                    missing = [p for p in cells if p not in s][0]
                    mr, mc = missing
                    if missing == (r, c):
                        kind = 'BR'
                    elif missing == (r, c + 1):
                        kind = 'BL'
                    elif missing == (r + 1, c):
                        kind = 'TR'
                    else:
                        kind = 'TL'
                    marker_color = v
                    marker_corner = (mr, mc)
                    marker_kind = kind
                    break
            if marker_color is not None:
                break
        if marker_color is not None:
            break

    # Fallback: any 2x2 L of a non-bg colour.
    if marker_color is None:
        for v, coords in colors.items():
            s = set(coords)
            for r in range(H - 1):
                for c in range(W - 1):
                    cells = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
                    if sum(1 for p in cells if p in s) == 3:
                        missing = [p for p in cells if p not in s][0]
                        mr, mc = missing
                        if missing == (r, c):
                            kind = 'BR'
                        elif missing == (r, c + 1):
                            kind = 'BL'
                        elif missing == (r + 1, c):
                            kind = 'TR'
                        else:
                            kind = 'TL'
                        marker_color = v
                        marker_corner = (mr, mc)
                        marker_kind = kind
                        break
                if marker_color is not None:
                    break
            if marker_color is not None:
                break

    # ------------------------------------------------------------------
    # 2) Extract solid rectangular tiles made of non-background,
    #    non-marker cells.
    # ------------------------------------------------------------------
    blocked = [[False] * W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if grid[r][c] in (bg, marker_color):
                blocked[r][c] = True

    seen = [[False] * W for _ in range(H)]
    pieces = []

    for r in range(H):
        for c in range(W):
            if blocked[r][c] or seen[r][c]:
                continue

            stack = [(r, c)]
            seen[r][c] = True
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W:
                        if not seen[ny][nx] and not blocked[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))

            r0 = min(y for y, _ in comp)
            r1 = max(y for y, _ in comp)
            c0 = min(x for _, x in comp)
            c1 = max(x for _, x in comp)
            ph = r1 - r0 + 1
            pw = c1 - c0 + 1

            # All given puzzles contain filled rectangular pieces.
            if len(comp) == ph * pw:
                piece = [grid[r0 + i][c0 + j] for j in range(c0, c1 + 1)
                         for i in range(0)]  # placeholder to keep pyright-ish
                piece = [[grid[r0 + i][c0 + j] for j in range(pw)]
                         for i in range(ph)]
                pieces.append((ph, pw, piece))

    # If marker detection failed or pieces are empty, return background grid.
    if not pieces:
        return [[bg] * W for _ in range(H)]

    # ------------------------------------------------------------------
    # 3) Determine the assembled rectangle by exact packing of the tile
    #    sizes.  The examples require no rotation/reflection.
    # ------------------------------------------------------------------
    n = len(pieces)
    total_area = sum(h * w for h, w, _ in pieces)
    max_h = max(h for h, _, _ in pieces)
    max_w = max(w for _, w, _ in pieces)

    # Candidate target dimensions.  Prefer near-square, then smaller height.
    dims = []
    for Ht in range(max_h, total_area + 1):
        if total_area % Ht:
            continue
        Wt = total_area // Ht
        if Wt >= max_w:
            dims.append((Ht, Wt))
    dims.sort(key=lambda x: (abs(x[0] - x[1]), x[0], x[1]))

    placements = None
    Ht = Wt = None

    for Ht, Wt in dims:
        # Order pieces: largest area first helps search.
        order = sorted(range(n), key=lambda i: -(pieces[i][0] * pieces[i][1]))
        used = [False] * n
        pos = [0] * n

        # Cell occupancy for speed.
        occ = [[False] * Wt for _ in range(Ht)]

        def first_empty():
            for i in range(Ht):
                row = occ[i]
                for j in range(Wt):
                    if not row[j]:
                        return i, j
            return None

        def can_place(i, r, c):
            h, w, _ = pieces[i]
            if r < 0 or c < 0 or r + h > Ht or c + w > Wt:
                return False
            for x in range(r, r + h):
                row = occ[x]
                for y in range(c, c + w):
                    if row[y]:
                        return False
            return True

        def place(i, r, c):
            h, w, _ = pieces[i]
            for x in range(r, r + h):
                row = occ[x]
                for y in range(c, c + w):
                    row[y] = True

        def unplace(i, r, c):
            h, w, _ = pieces[i]
            for x in range(r, r + h):
                row = occ[x]
                for y in range(c, c + w):
                    row[y] = False

        def search():
            f = first_empty()
            if f is None:
                return True
            r, c = f
            for idx in order:
                if used[idx]:
                    continue
                # The first empty cell must be the top-left corner of the
                # rectangle placed there.
                if can_place(idx, r, c):
                    place(idx, r, c)
                    pos[idx] = (r, c)
                    used[idx] = True
                    if search():
                        used[idx] = False
                        unplace(idx, r, c)
                        return True
                    used[idx] = False
                    unplace(idx, r, c)
            return False

        if search():
            placements = pos[:]
            break

    if placements is None:
        return [[bg] * W for _ in range(H)]

    # ------------------------------------------------------------------
    # 4) Place the assembled rectangle using the marker corner.
    # ------------------------------------------------------------------
    mr, mc = marker_corner
    if marker_kind == 'TL':
        top, left = mr, mc
    elif marker_kind == 'TR':
        top, left = mr, mc - Wt + 1
    elif marker_kind == 'BL':
        top, left = mr - Ht + 1, mc
    else:  # 'BR'
        top, left = mr - Ht + 1, mc - Wt + 1

    out = [[bg] * W for _ in range(H)]

    for i, (r, c) in enumerate(placements):
        h, w, piece = pieces[i]
        gr = top + r
        gc = left + c
        if gr < 0 or gc < 0 or gr + h > H or gc + w > W:
            continue
        for rr in range(h):
            out_row = out[gr + rr]
            src_row = piece[rr]
            for cc in range(w):
                out_row[gc + cc] = src_row[cc]

    return out

