                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and mask[nr][nc]:
                    yield nr, nc

    def component(r0, c0):
        stack = [(r0, c0)]
        mask[r0][c0] = False
        cells = []
        while stack:
            r, c = stack.pop()
            cells.append((r, c))
            for nr, nc in neighbors(r, c):
                if mask[nr][nc]:
                    mask[nr][nc] = False
                    stack.append((nr, nc))
        return cells

    comps = []
    for r in range(H):
        for c in range(W):
            if mask[r][c]:
                comps.append(component(r, c))

    if not comps:
        return [[0]]

    def comp_info(cells):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        y0, y1 = min(rs), max(rs)
        x0, x1 = min(cs), max(cs)
        colors = set(int(grid[r][c]) for r, c in cells)
        return {
            "y0": y0, "y1": y1, "x0": x0, "x1": x1,
            "h": y1 - y0 + 1, "w": x1 - x0 + 1,
            "size": len(cells),
            "area": (y1 - y0 + 1) * (x1 - x0 + 1),
            "density": len(cells) / ((y1 - y0 + 1) * (x1 - x0 + 1)),
            "colors": colors,
            "non_bg": colors - {bg},
            "cells": cells,
        }

    infos = [comp_info(c) for c in comps]
    frame_color = max(
        (c for info in infos for c in info["non_bg"]),
        key=lambda x: max(info["size"] for info in infos if x in info["non_bg"]),
    )

    frame_infos = [info for info in infos if frame_color in info["non_bg"]]
    frame_boxes = []
    if frame_infos:
        best = max(frame_infos, key=lambda t: (t["area"], t["size"], t["h"] * t["w"]))
        frame_boxes.append((best["y0"], best["x0"], best["y1"], best["x1"]))

        # Other frame components may be additional horizontal slices of the frame.
        # Include them only if they are nearby and compatible in width.
        others = [t for t in frame_infos if t is not best]
        others.sort(key=lambda t: (abs(t["y0"] - best["y0"]), abs(t["x0"] - best["x0"])))
        for t in others:
            if t["w"] <= max(best["w"] + 2, 1):
                if (best["y1"] - best["y0"] + 1 + 2 >= abs(t["y0"] - best["y0"])
                    and best["x1"] - best["x0"] + 1 + 2 >= abs(t["x0"] - best["x0"])):
                    frame_boxes.append((t["y0"], t["x0"], t["y1"], t["x1"]))

    if frame_boxes:
        fy0 = min(b[0] for b in frame_boxes)
        fy1 = max(b[2] for b in frame_boxes)
        fx0 = min(b[1] for b in frame_boxes)
        fx1 = max(b[3] for b in frame_boxes)
    else:
        fy0 = min(t["y0"] for t in infos)
        fy1 = max(t["y1"] for t in infos)
        fx0 = min(t["x0"] for t in infos)
        fx1 = max(t["x1"] for t in infos)

    # Target canvas is the union of all frame boxes, expanded slightly if content lies outside.
    out_h = fy1 - fy0 + 1
    out_w = fx1 - fx0 + 1

    # If the frame is too small relative to all components, expand to the largest component.
    largest = max(infos, key=lambda t: (t["area"], t["size"]))
    if out_w < largest["w"]:
        out_w = largest["w"]
    if out_h < largest["h"]:
        out_h = largest["h"]

    # Keep content components.  A component is content if it has any non-frame color.
    content = []
    for info in infos:
        specials = info["non_bg"] - {frame_color}
        if not specials:
            continue
        content.append(info)

    if not content:
        # Only frame/background: output a rounded frame if available.
        res = [[frame_color] * out_w for _ in range(out_h)]
    else:
        # Sort content top-to-bottom, then left-to-right.
        content.sort(key=lambda t: (t["y0"], t["x0"]))

        # Estimate the vertical placement of each content component in the target.
        # Use its top offset from the frame top, clamped to the target height.
        placements = []
        for info in content:
            off = info["y0"] - fy0
            h = info["h"]
            top = max(0, min(off, max(0, out_h - h)))
            placements.append((top, info))

        # If placements overlap heavily, fall back to a centered vertical stack.
        def overlaps(a, b):
            ta, ia = a
            tb, ib = b
            return ta < tb + ib["h"] and tb < ta + ia["h"]

        stack_fallback = False
        if len(placements) > 1:
            cur = 0
            ok = True
            for top, info in sorted(placements, key=lambda x: x[0]):
                if top < cur:
                    ok = False
                    break
                cur = top + info["h"]
            if not ok or cur > out_h:
                stack_fallback = True

        if stack_fallback:
            order = sorted(range(len(content)), key=lambda i: (content[i]["y0"], content[i]["x0"]))
            top = 0
            new_placements = []
            for idx in order:
                info = content[idx]
                new_placements.append((top, info))
                top += info["h"]
            # If stacked height is too small, distribute extra rows evenly.
            extra = out_h - top
            if extra > 0 and new_placements:
                # Add extra space above/below/inside to mimic a framed display.
                # A simple robust choice: put extra rows at the bottom.
                # This case should be rare for the visible tests.
                pass
            placements = new_placements

        # Create canvas filled with background.
        canvas = [[bg] * out_w for _ in range(out_h)]

        # Draw frame as a rounded rectangle if a frame color is meaningful.
        if frame_color != bg:
            for r in range(out_h):
                for c in range(out_w):
                    # Rounded corners of radius 2, similar to the examples.
                    corner = 0
                    if r < 2 and c < 2:
                        corner = 1
                    elif r < 2 and c >= out_w - 2:
                        corner = 1
                    elif r >= out_h - 2 and c < 2:
                        corner = 1
                    elif r >= out_h - 2 and c >= out_w - 2:
                        corner = 1
                    # The examples keep most corners background; only use frame for border cells.
                    if r == 0 or r == out_h - 1 or c == 0 or c == out_w - 1:
                        if corner:
                            # Leave rounded corners as background.
                            pass
                        else:
                            canvas[r][c] = frame_color
                    else:
                        # Interior default is frame color when a solid frame is present,
                        # otherwise background.
                        if len(frame_boxes) > 0 and frame_color in infos[0]["non_bg"]:
                            # Use frame color inside if the frame component was dense.
                            pass

        # A safer approach: do not paint a guessed solid frame; let content and
        # frame pixels from the frame box determine non-background cells.
        canvas = [[bg] * out_w for _ in range(out_h)]

        # Paint all frame-box cells that are not background in the input, shifted into canvas.
        for info in frame_infos:
            dy = info["y0"] - fy0
            dx = info["x0"] - fx0
            for (r, c) in info["cells"]:
                v = int(grid[r][c])
                rr = (r - info["y0"]) + dy
                cc = (c - info["x0"]) + dx
                if 0 <= rr < out_h and 0 <= cc < out_w:
                    if v != bg:
                        canvas[rr][cc] = v

        # Paint content components, centering them horizontally.
        for top, info in placements:
            dx = (out_w - info["w"]) // 2
            for (r, c) in info["cells"]:
                v = int(grid[r][c])
                rr = (r - info["y0"]) + top
                cc = (c - info["x0"]) + dx
                if 0 <= rr < out_h and 0 <= cc < out_w and v != bg:
                    # Special colors should override frame/background.
                    if v == frame_color and canvas[rr][cc] not in (bg, frame_color):
                        continue
                    canvas[rr][cc] = v

        # Fill interior frame: if a cell is background but is enclosed by frame/special cells,
        # convert it to frame color. This recovers missing interior cells seen in examples.
        visited = [[False] * out_w for _ in range(out_h)]
        for r in range(out_h):
            for c in range(out_w):
                if canvas[r][c] != bg or visited[r][c]:
                    continue
                # Flood-fill background region.
                q = [(r, c)]
                visited[r][c] = True
                touches_border = False
                while q:
                    y, x = q.pop()
                    if y == 0 or x == 0 or y == out_h - 1 or x == out_w - 1:
                        touches_border = True
                    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < out_h and 0 <= nx < out_w and not visited[ny][nx] and canvas[ny][nx] == bg:
                            visited[ny][nx] = True
                            q.append((ny, nx))
                # If this background region does not touch the border, fill with frame color.
                if not touches_border and frame_color != bg:
                    q = [(r, c)]
                    visited[r][c] = True
                    while q:
                        y, x = q.pop()
                        canvas[y][x] = frame_color
                        for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < out_h and 0 <= nx < out_w and not visited[ny][nx] and canvas[ny][nx] == bg:
                                visited[ny][nx] = True
                                q.append((ny, nx))

        res = canvas

    # Remove completely empty top/bottom rows if the result is empty.
    while res and all(v == bg for v in res[0]):
        res.pop(0)
    while res and all(v == bg for v in res[-1]):
        res.pop()
    if not res:
        return [[bg]]

    return [[int(v) for v in row] for row in res]

import numpy as np
from collections import deque, defaultdict

def _components(grid: np.ndarray) -> list[dict]:
    H, W = grid.shape
    seen = np.zeros((H, W), dtype=bool)
    comps = []

    for r in range(H):
        for c in range(W):
            if seen[r, c] or grid[r, c] == 0:
                continue
            color = int(grid[r, c])
            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and grid[ny, nx] == color:
                        seen[ny, nx] = True
                        q.append((ny, nx))

            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            comps.append({
                "color": color,
                "cells": cells,
                "size": len(cells),
                "bbox": (min(ys), min(xs), max(ys), max(xs)),
            })
    return comps


def _normalize(cells):
    if not cells:
        return frozenset()
    min_y = min(y for y, _ in cells)
    min_x = min(x for _, x in cells)
    return frozenset((y - min_y, x - min_x) for y, x in cells)


def _d4_variants(shape):
    variants = set()
    for dy, dx in shape:
        variants.add((dy, dx))
    out = set()
    for base in list(variants):
        cur = [base]
        for _ in range(4):
            cur.append(tuple((x, -y) for y, x in cur[-1]))
        for p in cur:
            out.add(frozenset(p))
            out.add(frozenset((y, -x) for y, x in p))
    return out


def _d4_key(shape):
    return min(_d4_variants(shape))


def _shape_key(shape, allow_rotation):
    if allow_rotation:
        return _d4_key(shape)
    return shape


def _background_color(grid: np.ndarray):
    H, W = grid.shape
    border = []
    for c in range(W):
        border.append(grid[0, c])
        border.append(grid[H - 1, c])
    for r in range(H):
        border.append(grid[r, 0])
        border.append(grid[r, W - 1])
    counts = defaultdict(int)
    for v in border:
        counts[int(v)] += 1
    if counts:
        return max(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]
    return int(np.bincount(grid.ravel()).argmax())


def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape

    bg = _background_color(a)
    nonbg = np.where(a != bg, a, 0)

    comps = _components(nonbg)
    if not comps:
        return [[0] * W for _ in range(H)]

    # Template: largest component, preferring larger bounding box on ties.
    template = max(comps, key=lambda c: (c["size"], c["bbox"][2] - c["bbox"][0] + 1, c["bbox"][3] - c["bbox"][1] + 1))
    tcolor = template["color"]
    r0, c0, r1, c1 = template["bbox"]
    h = r1 - r0 + 1
    w = c1 - c0 + 1

    out = np.full((h, w), tcolor, dtype=int)

    # Hole components inside template bounding box.
    hole_grid = (a[r0:r1 + 1, c0:c1 + 1] != tcolor)
    if not hole_grid.any():
        return [[int(v) for v in row] for row in out.tolist()]

    seen = np.zeros((h, w), dtype=bool)
    holes = []
    for y in range(h):
        for x in range(w):
            if not hole_grid[y, x] or seen[y, x]:
                continue
            q = deque([(y, x)])
            seen[y, x] = True
            cells = []
            while q:
                cy, cx = q.popleft()
                cells.append((cy, cx))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = cy + dy, cx + dx
                    if 0 <= ny < h and 0 <= nx < w and hole_grid[ny, nx] and not seen[ny, nx]:
                        seen[ny, nx] = True
                        q.append((ny, nx))
            holes.append(cells)

    # Candidate components are all non-template components.
    candidates = [c for c in comps if c is not template]

    # If exact orientation matching is impossible for some hole, fall back to rotation/reflection.
    # Prefer exact whenever any exact candidate exists.
    exact_shapes = [_normalize(c["cells"]) for c in candidates]
    d4_shapes = [_d4_key(s) for s in exact_shapes]

    exact_by_shape = defaultdict(list)
    d4_by_shape = defaultdict(list)
    for c, es, ds in zip(candidates, exact_shapes, d4_shapes):
        exact_by_shape[es].append(c)
        d4_by_shape[ds].append(c)

    def score(cands):
        # Mode by number of matching components, then total pixels, then color.
        by_color = defaultdict(lambda: [0, 0])
        for c in cands:
            by_color[c["color"]][0] += 1
            by_color[c["color"]][1] += c["size"]
        if not by_color:
            return None
        return max(by_color.items(), key=lambda kv: (kv[1][0], kv[1][1], -kv[0]))[0]

    for hole_cells in holes:
        shape = _normalize(hole_cells)
        dshape = _d4_key(shape)

        cands = exact_by_shape.get(shape, [])
        if cands:
            fill = score(cands)
        else:
            cands = d4_by_shape.get(dshape, [])
            fill = score(cands) if cands else None

        if fill is None:
            # Conservative fallback: most frequent candidate color overall.
            allc = candidates
            fill = score(allc) if allc else int(tcolor)

        for y, x in hole_cells:
            out[y, x] = int(fill)

    return [[int(v) for v in row] for row in out.tolist()]

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    a = np.array(grid, dtype=int)
    H, W = a.shape

    def neighbors(r, c):
        yield (r - 1, c)
        yield (r + 1, c)
        yield (r, c - 1)
        yield (r, c + 1)

    def components(color):
        """Return list of cells for each connected component of color."""
        comp_id = np.full((H, W), -1, dtype=int)
        comps = []
        for r in range(H):
            for c in range(W):
                if a[r, c] == color and comp_id[r, c] == -1:
                    q = deque([(r, c)])
                    comp_id[r, c] = len(comps)
                    cells = []
                    while q:
                        x, y = q.popleft()
                        cells.append((x, y))
                        for nx, ny in neighbors(x, y):
                            if 0 <= nx < H and 0 <= ny < W:
                                if a[nx, ny] == color and comp_id[nx, ny] == -1:
                                    comp_id[nx, ny] = len(comps)
                                    q.append((nx, ny))
                    comps.append(cells)
        return comps

    colors = set(int(v) for row in a for v in row)

    singleton_cell_of = {}
    valid_fill_cells = set()
    selected_sources = set()

    # First pass: singleton cells of colors that have at least one component
    # with more than one cell.  These are the possible source colors.
    source_like = {}
    for col in colors:
        comps = components(col)
        big = [cells for cells in comps if len(cells) > 1]
        singletons = [cells[0] for cells in comps if len(cells) == 1]
        if singletons and big:
            source_like[col] = (singletons, big)

    # Fill cells are singletons adjacent to a singleton of a source-like color.
    # The same cell may be used by more than one source.
    for src, (singles, big) in source_like.items():
        for sr, sc in singles:
            for nr, nc in neighbors(sr, sc):
                if 0 <= nr < H and 0 <= nc < W:
                    fcol = int(a[nr, nc])
                    if fcol == src:
                        continue
                    fcomps = components(fcol)
                    if any(len(cells) == 1 and cells[0] == (nr, nc) for cells in fcomps):
                        valid_fill_cells.add((nr, nc, fcol))

    # Select sources whose singleton is adjacent to at least one valid fill cell.
    for src, (singles, big) in source_like.items():
        for sr, sc in singles:
            for nr, nc in neighbors(sr, sc):
                if (nr, nc, int(a[nr, nc])) in valid_fill_cells:
                    selected_sources.add(src)
                    singleton_cell_of[src] = (sr, sc)
                    break
            if src in selected_sources:
                break

    # If a selected source has several singleton candidates, keep the first found.
    # For deterministic behavior, sort sources by color.
    boxes = []
    for src in sorted(selected_sources):
        comps = components(src)
        big = [cells for cells in comps if len(cells) > 1]
        singles = [cells[0] for cells in comps if len(cells) == 1]
        if not big or not singles:
            continue

        # bounding box of all non-singleton components
        rmin = min(min(r for r, c in cells) for cells in big)
        rmax = max(max(r for r, c in cells) for cells in big)
        cmin = min(min(c for r, c in cells) for cells in big)
        cmax = max(max(c for r, c in cells) for cells in big)

        # choose a fill cell adjacent to this singleton
        fill_col = None
        for sr, sc in singles:
            cand = []
            for nr, nc in neighbors(sr, sc):
                if (nr, nc, int(a[nr, nc])) in valid_fill_cells:
                    cand.append((int(a[nr, nc]), nr, nc))
            if cand:
                # Prefer the valid fill with the smallest color, then row/col.
                cand.sort()
                fill_col = cand[0][0]
                break
        if fill_col is None:
            continue
        boxes.append((src, fill_col, rmin, rmax, cmin, cmax))

    # Build output.
    out = a.copy()

    # Protective cells: all cells of selected source colors, all valid fill cells,
    # and all original cells that are not overwritten by the intended rectangle logic.
    protect = np.zeros((H, W), dtype=bool)
    for src in selected_sources:
        for r in range(H):
            for c in range(W):
                if a[r, c] == src:
                    protect[r, c] = True
    for r, c, col in valid_fill_cells:
        protect[r, c] = True

    # Apply rectangles in descending fill color, so smaller fill colors win overlaps.
    for src, fill, rmin, rmax, cmin, cmax in sorted(boxes, key=lambda x: -x[1]):
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                if not protect[r, c]:
                    out[r, c] = fill

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.asarray(grid, dtype=int)
    if a.size == 0:
        return [list(map(int, row)) for row in grid]

    H, W = a.shape

    def four_neighbors(r, c):
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < H and 0 <= nc < W:
                yield nr, nc

    # Connected components by 4-connectivity.
    def get_components():
        comp_id = np.full((H, W), -1, dtype=int)
        comps = []
        for r in range(H):
            for c in range(W):
                if comp_id[r, c] != -1:
                    continue
                col = a[r, c]
                q = deque([(r, c)])
                comp_id[r, c] = len(comps)
                cells = [(r, c)]
                while q:
                    x, y = q.popleft()
                    for nx, ny in four_neighbors(x, y):
                        if comp_id[nx, ny] == -1 and a[nx, ny] == col:
                            comp_id[nx, ny] = len(comps)
                            q.append((nx, ny))
                            cells.append((nx, ny))
                comps.append((col, cells))
        return comps

    comps = get_components()
    by_color = {}
    for col, cells in comps:
        by_color.setdefault(col, []).append(cells)

    # A rectangle is triggered by two adjacent singleton cells:
    #   <fill_color> next to <target_color>.
    # The target color must have at least two non-singleton components.
    rects = []
    seen_triggers = set()

    for r in range(H):
        for c in range(W):
            cell_col = int(a[r, c])
            if len(by_color.get(cell_col, [])) != 1 or by_color[cell_col][0][0] != (r, c):
                continue
            for nr, nc in four_neighbors(r, c):
                other_col = int(a[nr, nc])
                if other_col == cell_col:
                    continue
                other_cells = by_color.get(other_col, [])
                if not other_cells or other_cells[0] != [(nr, nc)]:
                    continue

                key = frozenset([(r, c), (nr, nc)])
                if key in seen_triggers:
                    continue
                seen_triggers.add(key)

                target_comps = [cells for cells in by_color.get(other_col, []) if len(cells) > 1]
                if len(target_comps) < 2:
                    continue

                # Use the two most extreme components in the main diagonal direction.
                # In all examples this is: one closest to top-left, one closest to bottom-right.
                # Score components so that the intended pair is selected even when extra
                # components of the same color exist.
                def diag_score(cells):
                    # Prefer components that are high/left and low/right.
                    # We simply pick min row+(-col) for top-left and max row+col for bottom-right.
                    pass

                # Select top-left-most and bottom-right-most non-singleton components.
                def top_left_score(cells):
                    return min(r - c for r, c in cells)
                def bottom_right_score(cells):
                    return max(r + c for r, c in cells)

                tl_comp = min(target_comps, key=lambda cells: (top_left_score(cells),
                                                               min(r for r, c in cells),
                                                               min(c for r, c in cells)))
                br_comp = max(target_comps, key=lambda cells: (bottom_right_score(cells),
                                                               max(r for r, c in cells),
                                                               max(c for r, c in cells)))
                if tl_comp is br_comp:
                    continue

                rmin = min(min(r for r, c in tl_comp), min(r for r, c in br_comp))
                rmax = max(max(r for r, c in tl_comp), max(r for r, c in br_comp))
                cmin = min(min(c for r, c in tl_comp), min(c for r, c in br_comp))
                cmax = max(max(c for r, c in tl_comp), max(c for r, c in br_comp))

                # If the pair is a top-left -> bottom-right staircase with an empty column
                # between their horizontal spans, clip the right edge to the left column
                # of the bottom-right component.  This matches the ARC examples.
                tl_rmin = min(r for r, c in tl_comp)
                tl_cmax = max(c for r, c in tl_comp)
                br_rmin = min(r for r, c in br_comp)
                br_cmin = min(c for r, c in br_comp)
                br_cmax = max(c for r, c in br_comp)

                if tl_rmin < br_rmin and tl_cmax < br_cmin and br_cmin >= tl_cmax + 2:
                    cmax = br_cmin

                rects.append((cell_col, rmin, rmax, cmin, cmax))

    out = a.copy()

    # Draw rectangles.  If rectangles overlap, the smaller fill color wins,
    # which is consistent with all examples.
    for fill, rmin, rmax, cmin, cmax in sorted(rects, key=lambda x: x[0]):
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                out[r, c] = fill

    # Original non-background cells are preserved.  The background is inferred
    # as the most common color in the input.
    colors, counts = np.unique(a, return_counts=True)
    bg = int(colors[np.argmax(counts)])
    for r in range(H):
        for c in range(W):
            if a[r, c] != bg:
                out[r, c] = a[r, c]

    return out.tolist()

