    if unique_non_bg:
        fill_color = max(unique_non_bg)
    else:
        # Fallback, though the given puzzles have a unique marker.
        non_bg = [c for c in counts if c != bg]
        fill_color = max(non_bg) if non_bg else bg

    # Mark all background cells connected to the border (outside background).
    seen = [[False] * w for _ in range(h)]
    q = deque()

    def try_add(i, j):
