            seen[i][j] = True
            q.append((i, j))

    for i in range(h):
        try_add(i, 0)
        try_add(i, w - 1)
    for j in range(w):
        try_add(0, j)
        try_add(h - 1, j)

    while q:
        i, j = q.popleft()
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < h and 0 <= nj < w and not seen[ni][nj] and grid[ni][nj] == bg:
                seen[ni][nj] = True
